int handle_request(const void *data, uint32_t length) {
    char buffer[4096];
    if (!validate_length(length)) return -1;
    copy_to_buffer(buffer, data, length);
    return 0;
}

bool validate_length(uint32_t length) {
    return length <= 4096;
}

